import{_ as o,o as t,c as i,ae as e}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"iCost 明細インポート","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/08-icost-bill-import-guide.md","filePath":"v1/ja/guide/08-icost-bill-import-guide.md"}'),l={name:"v1/ja/guide/08-icost-bill-import-guide.md"};function r(s,a,n,c,d,h){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="icost-明細インポート" tabindex="-1">iCost 明細インポート <a class="header-anchor" href="#icost-明細インポート" aria-label="Permalink to &quot;iCost 明細インポート&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>Koala は iCost の <strong>Excel エクスポート</strong>（<code>.xlsx</code> / <code>.xls</code>）をインポートできます。iCost の CSV は非対応です。</p><h2 id="📤-icost-側-エクスポート-簡易" tabindex="-1">📤 iCost 側：エクスポート（簡易） <a class="header-anchor" href="#📤-icost-側-エクスポート-簡易" aria-label="Permalink to &quot;📤 iCost 側：エクスポート（簡易）&quot;">​</a></h2><p>iCost の設定/その他から「エクスポート/データエクスポート」を開き、形式を <strong>Excel</strong> にして保存します。</p><h2 id="📥-koala-側-インポート" tabindex="-1">📥 Koala 側：インポート <a class="header-anchor" href="#📥-koala-側-インポート" aria-label="Permalink to &quot;📥 Koala 側：インポート&quot;">​</a></h2><ol><li>設定 → 明細インポート</li><li>インポート元を <strong>iCost</strong> に設定</li><li>Excel ファイルを選択 → 帳本を選択</li><li>解析 → プレビュー → インポート</li></ol><h2 id="⚠️-注意" tabindex="-1">⚠️ 注意 <a class="header-anchor" href="#⚠️-注意" aria-label="Permalink to &quot;⚠️ 注意&quot;">​</a></h2><ul><li>解析はヘッダー行に「日期」が含まれることを前提にしています。エクスポート言語を選べる場合は中国語ヘッダーでの出力を推奨します。</li><li>同じファイルを重複してインポートすると重複明細が作成される場合があります。</li></ul><hr><p><strong>最終更新</strong>：2026 年 4 月</p>',11)])])}const p=o(l,[["render",r]]);export{_ as __pageData,p as default};
